import os
from typing import Any, Dict, List, Optional

import requests


class AzureDocumentIntelligenceExtractor:
    """
    Extracts OCR and layout elements from a document using Azure AI Document Intelligence.
    Requires:
      - AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT
      - AZURE_DOCUMENT_INTELLIGENCE_KEY
    """

    def __init__(
        self,
        endpoint: Optional[str] = None,
        api_key: Optional[str] = None,
        api_version: str = "2024-11-30",
        model_id: str = "prebuilt-layout",
        timeout: int = 60,
    ) -> None:
        self.endpoint = (endpoint or os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT") or "").rstrip("/")
        self.api_key = api_key or os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY") or os.getenv("AZURE_AI_DOCUMENT_INTELLIGENCE_KEY") or ""
        self.api_version = api_version
        self.model_id = model_id
        self.timeout = timeout

        if not self.endpoint:
            raise ValueError("Missing Azure Document Intelligence endpoint.")
        if not self.api_key:
            raise ValueError("Missing Azure Document Intelligence API key.")

    def _headers(self, content_type: str) -> Dict[str, str]:
        return {
            "Ocp-Apim-Subscription-Key": self.api_key,
            "Content-Type": content_type,
        }

    def extract(self, document_path: str) -> Dict[str, Any]:
        with open(document_path, "rb") as f:
            data = f.read()

        analyze_url = (
            f"{self.endpoint}/documentintelligence/documentModels/"
            f"{self.model_id}:analyze?api-version={self.api_version}"
        )

        response = requests.post(
            analyze_url,
            headers=self._headers("application/octet-stream"),
            data=data,
            timeout=self.timeout,
        )
        response.raise_for_status()

        operation_url = response.headers.get("operation-location")
        if not operation_url:
            raise RuntimeError("Azure Document Intelligence did not return an operation-location header.")

        result = self._poll(operation_url)
        return self._normalize(result)

    def _poll(self, operation_url: str) -> Dict[str, Any]:
        while True:
            resp = requests.get(
                operation_url,
                headers={"Ocp-Apim-Subscription-Key": self.api_key},
                timeout=self.timeout,
            )
            resp.raise_for_status()
            payload = resp.json()
            status = payload.get("status")

            if status in {"succeeded", "failed", "canceled"}:
                if status != "succeeded":
                    raise RuntimeError(f"Document analysis did not succeed: {status}")
                return payload

    def _normalize(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        analyze_result = payload.get("analyzeResult", {}) or {}

        pages_out: List[Dict[str, Any]] = []
        for page in analyze_result.get("pages", []) or []:
            lines = []
            for line in page.get("lines", []) or []:
                lines.append(
                    {
                        "content": line.get("content"),
                        "polygon": line.get("polygon"),
                        "span": line.get("span"),
                    }
                )
            words = []
            for word in page.get("words", []) or []:
                words.append(
                    {
                        "content": word.get("content"),
                        "confidence": word.get("confidence"),
                        "polygon": word.get("polygon"),
                        "span": word.get("span"),
                    }
                )

            pages_out.append(
                {
                    "page_number": page.get("pageNumber"),
                    "width": page.get("width"),
                    "height": page.get("height"),
                    "unit": page.get("unit"),
                    "lines": lines,
                    "words": words,
                }
            )

        tables_out: List[Dict[str, Any]] = []
        for table in analyze_result.get("tables", []) or []:
            cells = []
            for cell in table.get("cells", []) or []:
                cells.append(
                    {
                        "row_index": cell.get("rowIndex"),
                        "column_index": cell.get("columnIndex"),
                        "content": cell.get("content"),
                        "kind": cell.get("kind"),
                        "row_span": cell.get("rowSpan"),
                        "column_span": cell.get("columnSpan"),
                        "bounding_regions": cell.get("boundingRegions"),
                    }
                )
            tables_out.append(
                {
                    "row_count": table.get("rowCount"),
                    "column_count": table.get("columnCount"),
                    "cells": cells,
                    "bounding_regions": table.get("boundingRegions"),
                }
            )

        paragraphs_out = []
        for para in analyze_result.get("paragraphs", []) or []:
            paragraphs_out.append(
                {
                    "content": para.get("content"),
                    "role": para.get("role"),
                    "span": para.get("span"),
                    "bounding_regions": para.get("boundingRegions"),
                }
            )

        return {
            "model_id": self.model_id,
            "pages": pages_out,
            "tables": tables_out,
            "paragraphs": paragraphs_out,
            "raw": payload,
        }


def extract_layout(document_path: str, endpoint: Optional[str] = None, api_key: Optional[str] = None) -> Dict[str, Any]:
    extractor = AzureDocumentIntelligenceExtractor(endpoint=endpoint, api_key=api_key)
    return extractor.extract(document_path)
